457	        resolve("req-rf-1", "res-16", "obs-16", 1, 2,
458	                "站点C", "1.0", "备注", Map.of(), "op")
459	                .andExpect(status().isBadRequest());
460	        assertThat(requestLogCount("req-rf-1")).isZero();
461	        // 同一 requestId 与 resolutionId 换上合法参数后成功
462	        resolve("req-rf-1", "res-16", "obs-16", 1, 2,
463	                "站点C", "1.0", "备注", Map.of("location", "CANDIDATE"), "op")
464	                .andExpect(status().isOk())
465	                .andExpect(jsonPath("$.version").value(3));
466	        assertThat(requestLogCount("req-rf-1")).isEqualTo(1);
467	        assertThat(resolutionCount("obs-16")).isEqualTo(1);
468	    }
469	
470	    // ---------- 读数冲突与历史不可变 ----------
471	
472	    @Test
473	    void resolveReadingConflictComparedNumerically() throws Exception {
474	        create("req-rn2-0", "obs-17", "站点A", "1.0", "备注").andExpect(status().isCreated());
475	        merge("req-rn2-1", "obs-17", 1, "站点A", "2.5", "备注").andExpect(status().isOk());
476	        // 离线端基于 v1 把读数改为 1.5：与服务端 2.5 冲突
477	        merge("req-rn2-2", "obs-17", 1, "站点A", "1.5", "备注")
478	                .andExpect(status().isConflict())
479	                .andExpect(jsonPath("$.conflictFields[0]").value("reading"));
480	        resolve("req-rn2-3", "res-17", "obs-17", 1, 2,
481	                "站点A", "1.5", "备注", Map.of("reading", "CANDIDATE"), "op")
482	                .andExpect(status().isOk())
483	                .andExpect(jsonPath("$.version").value(3))
484	                .andExpect(jsonPath("$.reading").value("1.5"));
485	
486	        // 候选读数 1.50 与当前 1.5 数值相等：两边改为相同值，无冲突自动接受，结果与当前相同不加版本
487	        resolve("req-rn2-4", "res-17b", "obs-17", 1, 3,
488	                "站点A", "1.50", "备注", Map.of(), "op")
489	                .andExpect(status().isOk())
490	                .andExpect(jsonPath("$.version").value(3))
491	                .andExpect(jsonPath("$.contentChanged").value(false))
492	                .andExpect(jsonPath("$.reading").value("1.5"));
493	    }
494	
495	    @Test
496	    void resolutionHistoryIsOrderedAndRecordsRemainImmutable() throws Exception {
497	        create("req-rh-0", "obs-18", "站点A", "1.0", "备注").andExpect(status().isCreated());
498	        merge("req-rh-1", "obs-18", 1, "站点B", "1.0", "备注").andExpect(status().isOk());
499	        // 第一次解决：站点B/C 冲突选 CANDIDATE，备注自动合并为离线备注 → v3
500	        resolve("req-rh-2", "res-18a", "obs-18", 1, 2,
501	                "站点C", "1.0", "离线备注", Map.of("location", "CANDIDATE"), "op1")
502	                .andExpect(status().isOk())
503	                .andExpect(jsonPath("$.version").value(3));
504	        // 服务端 v4 改地点为站点D；离线端基于 v3 改地点为站点E
505	        merge("req-rh-3", "obs-18", 3, "站点D", "1.0", "离线备注").andExpect(status().isOk());
506	        resolve("req-rh-4", "res-18b", "obs-18", 3, 4,
507	                "站点E", "1.0", "离线备注", Map.of("location", "CANDIDATE"), "op2")
508	                .andExpect(status().isOk())
509	                .andExpect(jsonPath("$.version").value(5));
510	
511	        // 历史按解决时刻先后返回；每条记录不可变，始终指向解决时的版本
512	        mockMvc.perform(get("/api/observations/{id}/resolutions", "obs-18"))
513	                .andExpect(status().isOk())
514	                .andExpect(jsonPath("$[0].resolutionId").value("res-18a"))
515	                .andExpect(jsonPath("$[0].version").value(3))
516	                .andExpect(jsonPath("$[0].location").value("站点C"))
517	                .andExpect(jsonPath("$[0].note").value("离线备注"))
518	                .andExpect(jsonPath("$[0].operator").value("op1"))
519	                .andExpect(jsonPath("$[1].resolutionId").value("res-18b"))
520	                .andExpect(jsonPath("$[1].version").value(5))
521	                .andExpect(jsonPath("$[1].location").value("站点E"));
522	        mockMvc.perform(get("/api/observations/resolutions/{resolutionId}", "res-18a"))
523	                .andExpect(status().isOk())
