526	                .andExpect(jsonPath("$.location").value("站点C"));
527	        mockMvc.perform(get("/api/observations/{id}", "obs-18"))
528	                .andExpect(jsonPath("$.version").value(5))
529	                .andExpect(jsonPath("$.location").value("站点E"));
