package com.example.starter.observation;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.util.List;
import java.util.Optional;

/**
 * 观测附件持久化：attachment 表登记附件元数据与原始内容摘要；原始摘要只增不改，仅物理清除可置空。
 * 所有 SQL 使用参数化查询。
 */
@Repository
public class AttachmentRepository {

    private static final RowMapper<AttachmentRecord> ATTACHMENT_MAPPER = (rs, rowNum) -> new AttachmentRecord(
            rs.getString("attachment_id"),
            rs.getString("observation_id"),
            rs.getString("content_summary"),
            rs.getBoolean("content_purged"),
            rs.getTimestamp("created_at_utc").toInstant(),
            rs.getTimestamp("purged_at_utc") == null ? null : rs.getTimestamp("purged_at_utc").toInstant());

    private final JdbcTemplate jdbcTemplate;

    public AttachmentRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 登记附件元数据；attachment_id 主键冲突时抛出重复键异常。
     */
    public void insert(AttachmentRecord record) {
        jdbcTemplate.update(
                "INSERT INTO attachment (attachment_id, observation_id, content_summary, content_purged, "
                        + "created_at_utc, purged_at_utc, created_at) VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                record.attachmentId(), record.observationId(), record.contentSummary(), record.contentPurged(),
                Timestamp.from(record.createdAtUtc()),
                record.purgedAtUtc() == null ? null : Timestamp.from(record.purgedAtUtc()));
    }

    /**
     * 按附件标识查询；不存在时返回空。
     */
    public Optional<AttachmentRecord> findById(String attachmentId) {
        return jdbcTemplate.query(
                        "SELECT attachment_id, observation_id, content_summary, content_purged, "
                                + "created_at_utc, purged_at_utc FROM attachment WHERE attachment_id = ?",
                        ATTACHMENT_MAPPER, attachmentId)
                .stream().findFirst();
    }

    /**
     * 按附件标识查询并加行锁（SELECT ... FOR UPDATE），用于写事务内串行化同一附件的并发脱敏。
     */
    public Optional<AttachmentRecord> findByIdForUpdate(String attachmentId) {
        return jdbcTemplate.query(
                        "SELECT attachment_id, observation_id, content_summary, content_purged, "
                                + "created_at_utc, purged_at_utc FROM attachment WHERE attachment_id = ? FOR UPDATE",
                        ATTACHMENT_MAPPER, attachmentId)
                .stream().findFirst();
    }

    /**
     * 按观测记录查询全部附件，按附件标识排序，保证公开列表顺序稳定。
     */
    public List<AttachmentRecord> findByObservationId(String observationId) {
        return jdbcTemplate.query(
                "SELECT attachment_id, observation_id, content_summary, content_purged, "
                        + "created_at_utc, purged_at_utc FROM attachment WHERE observation_id = ? "
                        + "ORDER BY attachment_id ASC",
                ATTACHMENT_MAPPER, observationId);
    }

    /**
     * 物理清除附件原始内容：摘要置空、标记已清除并记录清除时刻；已清除的附件重复调用为无操作。
     */
    public void purgeContent(String attachmentId, java.time.Instant purgedAtUtc) {
        jdbcTemplate.update(
                "UPDATE attachment SET content_summary = NULL, content_purged = TRUE, purged_at_utc = ? "
                        + "WHERE attachment_id = ?",
                Timestamp.from(purgedAtUtc), attachmentId);
    }
}

package com.example.starter.observation;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.util.Optional;

/**
 * 脱敏规则版本持久化：redaction_rule 表登记规则版本；撤销仅更新状态与撤销时刻，登记行永不删除。
 * 所有 SQL 使用参数化查询。
 */
@Repository
public class RedactionRuleRepository {

    private static final RowMapper<RedactionRuleRecord> RULE_MAPPER = (rs, rowNum) -> new RedactionRuleRecord(
            rs.getString("rule_version"),
            rs.getString("description"),
            "ACTIVE".equals(rs.getString("status")),
            rs.getString("revoked_reason"),
            rs.getTimestamp("registered_at_utc").toInstant(),
            rs.getTimestamp("revoked_at_utc") == null ? null : rs.getTimestamp("revoked_at_utc").toInstant());

    private final JdbcTemplate jdbcTemplate;

    public RedactionRuleRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 登记规则版本；rule_version 主键冲突时抛出重复键异常。
     */
    public void insert(RedactionRuleRecord record) {
        jdbcTemplate.update(
                "INSERT INTO redaction_rule (rule_version, description, status, revoked_reason, "
                        + "registered_at_utc, revoked_at_utc, created_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                record.ruleVersion(), record.description(), record.active() ? "ACTIVE" : "REVOKED",
                record.revokedReason(), Timestamp.from(record.registeredAtUtc()),
                record.revokedAtUtc() == null ? null : Timestamp.from(record.revokedAtUtc()));
    }

    /**
     * 按规则版本查询；不存在时返回空。
     */
    public Optional<RedactionRuleRecord> findByRuleVersion(String ruleVersion) {
        return jdbcTemplate.query(
                        "SELECT rule_version, description, status, revoked_reason, registered_at_utc, revoked_at_utc "
                                + "FROM redaction_rule WHERE rule_version = ?",
                        RULE_MAPPER, ruleVersion)
                .stream().findFirst();
    }

    /**
     * 撤销规则版本：置状态、原因与撤销时刻；仅影响后续新脱敏请求，不回写既有脱敏版本。
     */
    public void revoke(String ruleVersion, String reason, java.time.Instant revokedAtUtc) {
        jdbcTemplate.update(
                "UPDATE redaction_rule SET status = 'REVOKED', revoked_reason = ?, revoked_at_utc = ? "
                        + "WHERE rule_version = ?",
                reason, Timestamp.from(revokedAtUtc), ruleVersion);
    }
}

package com.example.starter.observation;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.util.List;
import java.util.Optional;

/**
 * 附件脱敏版本持久化：attachment_redaction 行只增不改；撤销仅更新状态、原因与撤销时刻。
 * 所有 SQL 使用参数化查询。
 */
@Repository
public class AttachmentRedactionRepository {

    private static final RowMapper<AttachmentRedactionRecord> REDACTION_MAPPER =
            (rs, rowNum) -> new AttachmentRedactionRecord(
                    rs.getString("redaction_id"),
                    rs.getString("observation_id"),
                    rs.getString("attachment_id"),
                    rs.getInt("redaction_version"),
                    rs.getString("request_id"),
                    rs.getString("rule_version"),
                    rs.getString("display_summary"),
                    rs.getString("replacement_note"),
                    "ACTIVE".equals(rs.getString("status")),
                    rs.getString("revoke_reason"),
                    rs.getTimestamp("created_at_utc").toInstant(),
                    rs.getTimestamp("revoked_at_utc") == null ? null : rs.getTimestamp("revoked_at_utc").toInstant());

    private final JdbcTemplate jdbcTemplate;

    public AttachmentRedactionRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 插入一个脱敏版本；唯一键冲突（同附件同规则版本、同附件同版本号、同脱敏请求同附件）抛出重复键异常。
     */
    public void insert(AttachmentRedactionRecord record) {
        jdbcTemplate.update(
                "INSERT INTO attachment_redaction (redaction_id, observation_id, attachment_id, redaction_version, "
                        + "request_id, rule_version, display_summary, replacement_note, status, revoke_reason, "
                        + "created_at_utc, revoked_at_utc, created_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                record.redactionId(), record.observationId(), record.attachmentId(), record.redactionVersion(),
                record.requestId(), record.ruleVersion(), record.displaySummary(), record.replacementNote(),
                record.active() ? "ACTIVE" : "REVOKED", record.revokeReason(),
                Timestamp.from(record.createdAtUtc()),
                record.revokedAtUtc() == null ? null : Timestamp.from(record.revokedAtUtc()));
    }

    /**
     * 查询某附件当前最大脱敏版本号；无脱敏版本时返回空。
     */
    public Optional<Integer> findMaxVersion(String attachmentId) {
        return jdbcTemplate.query(
                        "SELECT MAX(redaction_version) AS max_version FROM attachment_redaction WHERE attachment_id = ?",
                        (rs, rowNum) -> rs.getInt("max_version"), attachmentId)
                .stream().filter(v -> v > 0).findFirst();
    }

    /**
     * 查询某附件最新有效（ACTIVE）脱敏版本；无有效活跃版本时返回空。
     */
    public Optional<AttachmentRedactionRecord> findLatestActive(String attachmentId) {
        return jdbcTemplate.query(
                        "SELECT redaction_id, observation_id, attachment_id, redaction_version, request_id, "
                                + "rule_version, display_summary, replacement_note, status, revoke_reason, "
                                + "created_at_utc, revoked_at_utc FROM attachment_redaction "
                                + "WHERE attachment_id = ? AND status = 'ACTIVE' "
                                + "ORDER BY redaction_version DESC LIMIT 1",
                        REDACTION_MAPPER, attachmentId)
                .stream().findFirst();
    }

    /**
     * 按附件与脱敏版本号查询；不存在时返回空。
     */
    public Optional<AttachmentRedactionRecord> findByVersion(String attachmentId, int redactionVersion) {
        return jdbcTemplate.query(
                        "SELECT redaction_id, observation_id, attachment_id, redaction_version, request_id, "
                                + "rule_version, display_summary, replacement_note, status, revoke_reason, "
                                + "created_at_utc, revoked_at_utc FROM attachment_redaction "
                                + "WHERE attachment_id = ? AND redaction_version = ?",
                        REDACTION_MAPPER, attachmentId, redactionVersion)
                .stream().findFirst();
    }

    /**
     * 查询某附件全部脱敏版本，按版本号升序，保证历史顺序稳定。
     */
    public List<AttachmentRedactionRecord> findByAttachmentId(String attachmentId) {
        return jdbcTemplate.query(
                "SELECT redaction_id, observation_id, attachment_id, redaction_version, request_id, "
                        + "rule_version, display_summary, replacement_note, status, revoke_reason, "
                        + "created_at_utc, revoked_at_utc FROM attachment_redaction "
                        + "WHERE attachment_id = ? ORDER BY redaction_version ASC",
                REDACTION_MAPPER, attachmentId);
    }

    /**
     * 按脱敏请求标识查询该请求生成的全部脱敏版本，按附件标识排序，保证重放响应顺序稳定。
     */
    public List<AttachmentRedactionRecord> findByRedactionId(String redactionId) {
        return jdbcTemplate.query(
                "SELECT redaction_id, observation_id, attachment_id, redaction_version, request_id, "
                        + "rule_version, display_summary, replacement_note, status, revoke_reason, "
                        + "created_at_utc, revoked_at_utc FROM attachment_redaction "
                        + "WHERE redaction_id = ? ORDER BY attachment_id ASC",
                REDACTION_MAPPER, redactionId);
    }

    /**
     * 撤销一个脱敏版本的公开展示资格：置状态、原因与撤销时刻；行与替换说明永久保留。
     */
