                .andExpect(jsonPath("$.items[0].originalSummary").value("原始敏感摘要"))
                .andExpect(jsonPath("$.items[0].displaySummary").doesNotExist());

        // 脱敏 r1 后合并生成 v2：固化 r1
        redact("req-fz-4", "red-1", "obs-1",
