                .andExpect(jsonPath("$.items[0].displaySummary").value("[REDACTED rule=rule-v1] 替换v1"));

        // 再次脱敏 r2 并撤销 r1：公开视图变为 r2，但 v2 固化证据仍引用 r1
        redact("req-fz-6", "red-2", "obs-1",
